(()=>{
'use strict';
if(window.__franklinLogFilesV2)return;
window.__franklinLogFilesV2=true;
const svg=n=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${n}"></use></svg>`;
let toastTimer;
function toast(text){document.querySelector('.helper-file-toast')?.remove();clearTimeout(toastTimer);const el=document.createElement('div');el.className='helper-file-toast';el.setAttribute('role','alert');const p=document.createElement('p');p.textContent=text;const close=document.createElement('button');close.type='button';close.setAttribute('aria-label','Dismiss file notification');close.innerHTML=svg('close');close.onclick=()=>el.remove();el.append(p,close);document.body.append(el);toastTimer=setTimeout(()=>el.remove(),6000);}
const valid=text=>!/\0/.test(text)&&/(GTA5 UUID|\[RAGE\]|\[macport\]|GTA V.*crash|Game hung for|Unable to find critical archive|compat built|ReflectionMSAA|sample count.*supported|memory:\s*footprint|d3d11\.dylib|CreateDXMTDevice|D3D11CreateDevice|datapatch:|no movies\/|terminated by signal|fatal error:|streamer:)/i.test(text);
function fallback(text,filename=''){const a=window.FranklinLogIntelligence?.analyze?.(text,{filename});return a?window.FranklinLogIntelligence.format(a):'I received the log, but I cannot identify the cause confidently yet. Please send run.log or run.prev.log from the same incident and ask in #support if the problem continues.';}
function attach(){
 const form=document.querySelector('.ask-franklin-form');if(!form||form.querySelector('.helper-attach'))return false;
 const send=form.querySelector('.ask-franklin-send'),question=form.querySelector('.ask-franklin-input');let file=null,excerpt='',fullText='',busy=false,revision=0;
 const input=document.createElement('input');input.type='file';input.accept='.log,.txt,text/plain';input.hidden=true;input.setAttribute('aria-label','Choose GTA V log');
 const pick=document.createElement('button');pick.type='button';pick.className='helper-attach';pick.setAttribute('aria-label','Attach GTA V log');pick.title='Attach GTA V log (.log or .txt)';pick.innerHTML=svg('paperclip');form.insertBefore(pick,send);form.append(input);
 const paste=document.createElement('button');paste.type='button';paste.className='helper-paste';paste.setAttribute('aria-label','Paste into message');paste.title='Paste';paste.innerHTML='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="4" width="8" height="4" rx="1"/><path d="M8 6H5v15h14V6h-3M8 12h8M8 16h6"/></svg>';form.insertBefore(paste,pick);
 paste.onclick=async()=>{try{const value=await navigator.clipboard.readText();if(!value){toast('Your clipboard is empty.');return;}const start=question.selectionStart??question.value.length,end=question.selectionEnd??start,next=question.value.slice(0,start)+value+question.value.slice(end);if(next.length>question.maxLength){toast('This text is too long. Attach a .log or .txt file instead.');return;}question.value=next;question.focus({preventScroll:true});question.setSelectionRange(start+value.length,start+value.length);question.dispatchEvent(new Event('input',{bubbles:true}));}catch{question.focus({preventScroll:true});toast('Clipboard access was blocked. Touch and hold the message field, then choose Paste.');}};
 form.classList.add('has-log-attachment');
 const bar=document.createElement('div');bar.className='helper-attached-file';bar.hidden=true;const name=document.createElement('span'),share=document.createElement('button'),remove=document.createElement('button');share.type=remove.type='button';share.innerHTML=svg('arrow-up-right');share.setAttribute('aria-label','Share original log file outside Franklin');share.title='Share original file outside Franklin';remove.innerHTML=svg('close');remove.setAttribute('aria-label','Remove attached log');bar.append(name,share,remove);form.before(bar);
 const note=document.createElement('p');note.className='helper-attachment-note';note.hidden=true;note.textContent='Press the yellow Send button to analyze this log. Franklin reads the full text locally and uses diagnostic evidence to identify the cause or failing subsystem.';bar.after(note);
 const clear=()=>{revision++;file=null;excerpt='';fullText='';delete form.dataset.logAttached;input.value='';bar.hidden=note.hidden=true;send.disabled=busy||!question.value.trim();pick.setAttribute('aria-label','Attach GTA V log');};
 document.addEventListener('franklin-disconnect',()=>{busy=false;clear();pick.disabled=false;document.querySelector('.helper-file-toast')?.remove();});pick.onclick=()=>input.click();remove.onclick=clear;
 input.onchange=async()=>{const selected=input.files?.[0];clear();if(!selected)return;if(!/\.(log|txt)$/i.test(selected.name)||selected.size>524288||selected.size===0){toast('Choose a GTA V .log or .txt file, up to 512 KB.');return;}const version=revision;try{const text=await selected.text();if(version!==revision)return;if(!valid(text)){toast('This file does not look like a GTA V diagnostic log. Choose run.log, run.prev.log, or crash-*.txt from GTA V > Logs.');return;}file=selected;form.dataset.logAttached='true';fullText=text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig,'[email removed]').replace(/(authorization\s*[:=]\s*|token\s*[:=]\s*|api[_-]?key\s*[:=]\s*)\S+/ig,'$1[removed]');const lines=fullText.split(/\r?\n/),indexes=new Set();lines.forEach((l,i)=>{if(i<40||i>=lines.length-90||/fatal|error|crash|exception|signal|memory|thermal|sample count|critical archive|compat built|GTA5 UUID|stalled|Game hung|SIG(?:SEGV|TRAP|ABRT|BUS)|d3d11|dxmt|metal|InternalCommandLibrary|CreateDXMTDevice|D3D11CreateDevice|SettingsDefaults|GetDisplayInfo|GenerateDefaultSettings|CVehicleStreamRenderGfx|guard word trashed|HasExpired|cloud hat|d3dr1|posthook|datapatch|no movies\/|previous run|terminated by signal|0xdddd|trevor3|docks_heista|fbi3|gunclub_shop/i.test(l))for(let j=Math.max(0,i-2);j<=Math.min(lines.length-1,i+2);j++)indexes.add(j);});excerpt=[...indexes].sort((a,b)=>a-b).map(i=>lines[i]).join('\n').slice(0,120000);name.textContent=selected.name+' · '+Math.ceil(selected.size/1024)+' KB';name.title=selected.name;bar.hidden=note.hidden=false;send.disabled=busy;share.hidden=!(navigator.canShare&&navigator.canShare({files:[selected]}));pick.setAttribute('aria-label','Replace attached GTA V log');}catch{toast('Unable to read this file. Please choose a text log.');}};
 question.addEventListener('input',()=>{queueMicrotask(()=>{if(file&&!busy)send.disabled=false;});});
 share.onclick=async()=>{if(!file)return;try{await navigator.share({files:[file],title:'GTA V support log'});}catch(e){if(e.name!=='AbortError')toast('Unable to share. Attach the log manually in Discord.');}};
 function message(text,role){const list=document.querySelector('.ask-franklin-messages');if(!list)return;const row=document.createElement('div');row.className='ask-franklin-message '+role+' helper-log-result';if(role==='bot'){const avatar=document.createElement('span');avatar.className='mini-avatar';avatar.textContent='F';row.append(avatar);}const bubble=document.createElement('div');bubble.className='bubble';bubble.style.whiteSpace='pre-wrap';bubble.textContent=text;row.append(bubble);list.append(row);list.scrollTop=list.scrollHeight;return bubble;}
 async function submit(e){const generation=window.FranklinSession?.generation;if(!file){if(/(?:check|review|analy[sz]e|cek|periksa).*\blog\b/i.test(question.value)){e.preventDefault();e.stopImmediatePropagation();toast('Attach run.log, run.prev.log, or crash-*.txt using the paperclip beside Send.');message('Please attach your GTA V log using the paperclip beside Send. Once selected, press Send to analyze it.','bot');}return;}e.preventDefault();e.stopImmediatePropagation();if(busy)return;busy=true;send.disabled=pick.disabled=true;const localText=fullText,text=excerpt,filename=file.name,q=question.value.trim();message((q?q+'\n':'')+'Attached log: '+filename,'user');question.value='';const bubble=message('Analyzing log evidence…','bot');clear();try{await window.FranklinSupportContext?.ingestLog(localText);const analysis=window.FranklinLogIntelligence?.analyze?.(localText,{filename})||null;let finalText='';if(analysis&&analysis.kind!=='unknown')finalText=window.FranklinLogIntelligence.format(analysis);else{const answer=await window.FranklinDeveloperKB?.answer((q||'GTA V diagnostic log')+'\n'+text);if(answer?.topic==='developer-troubleshooting'||answer?.topic==='developer-triage')finalText=answer.text;else finalText=analysis?window.FranklinLogIntelligence.format(analysis):fallback(localText,filename);}if(generation!==window.FranklinSession?.generation)return;await window.FranklinTyping.reveal(bubble,finalText);}catch{if(generation!==window.FranklinSession?.generation)return;await window.FranklinTyping.reveal(bubble,fallback(localText,filename));}finally{if(generation!==window.FranklinSession?.generation)return;busy=false;pick.disabled=false;send.disabled=!file&&!question.value.trim();const list=document.querySelector('.ask-franklin-messages');if(list)list.scrollTop=list.scrollHeight;}}
 send.addEventListener('click',e=>{if(file)submit(e);},true);question.addEventListener('keydown',e=>{if(file&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing)submit(e);},true);document.addEventListener('submit',e=>{if(e.target===form)submit(e);},true);return true;
}
const l=document.createElement('link');l.rel='stylesheet';l.href='franklin-log-files.css?v=20261031knowledge4';document.head.append(l);
if(!attach()){const observer=new MutationObserver(()=>{if(attach())observer.disconnect();});observer.observe(document.body,{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),30000);}
})();
